import sys

# Increase recursion depth just in case, though 26 nodes is small.
sys.setrecursionlimit(2000)

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n_str = next(iterator)
        N = int(n_str)
        S = next(iterator)
        T = next(iterator)
    except StopIteration:
        return

    # Map to store the required transformation for each character in S
    # mapping[char_in_S] = char_in_T
    mapping = {}

    # Step 1: Check consistency
    # If S[i] == S[j], then T[i] must equal T[j].
    # If S[i] maps to multiple different characters in T, it's impossible.
    for i in range(N):
        u = S[i]
        v = T[i]

        if u in mapping:
            if mapping[u] != v:
                print("-1")
                return
        else:
            mapping[u] = v

    # Step 2: Check for cycles in the mapping graph
    # The graph consists of characters 'a'-'z'.
    # An edge exists from u to mapping[u] if u is in mapping.
    # We only care about cycles involving characters that are actually in S.

    # We use a visited array to detect cycles.
    # States: 0 = unvisited, 1 = visiting (in current recursion stack), 2 = visited
    state = {c: 0 for c in "abcdefghijklmnopqrstuvwxyz"}

    def detect_cycle_dfs(u):
        state[u] = 1 # Mark as visiting
        if u in mapping:
            v = mapping[u]
            if state[v] == 1:
                return True # Cycle detected
            if state[v] == 0:
                if detect_cycle_dfs(v):
                    return True
        state[u] = 2 # Mark as visited
        return False

    for char in S:
        if state[char] == 0:
            if detect_cycle_dfs(char):
                print("-1")
                return

    # Step 3: Count operations
    # The number of operations is the number of unique characters in S 
    # that need to be changed (i.e., mapping[c] != c).
    # Each such character requires exactly one operation "replace c with mapping[c]".
    # Even if there are dependencies (chains), the count is simply the number of 
    # distinct source characters that are not fixed points.

    operations = 0
    for char in mapping:
        if mapping[char] != char:
            operations += 1

    print(operations)

if __name__ == '__main__':
    solve()

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        length = n + m - 1
        word = [''] * length

        # Step 1: Apply all 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                # Check for conflicts before assigning
                for j in range(m):
                    if word[i + j] != '' and word[i + j] != str2[j]:
                        return ""
                # Assign the substring
                for j in range(m):
                    word[i + j] = str2[j]

        # Step 2: Fill unset positions greedily
        for i in range(length):
            if word[i] == '':
                # Try characters from 'a' to 'z'
                for c in "abcdefghijklmnopqrstuvwxyz":
                    word[i] = c
                    # Check if this choice violates any 'F' constraint
                    # We only need to check 'F' constraints where the window [j, j+m-1] is fully determined.
                    # A window starting at j is fully determined by index i if j + m - 1 <= i.
                    # This implies j <= i - m + 1.
                    # Also, j must be a valid index in str1 (0 <= j < n).

                    valid = True
                    # Calculate the range of j to check
                    # Upper bound for j is i - m + 1. In Python range, the stop value is exclusive, so i - m + 2.
                    # Lower bound is 0.
                    start_j = 0
                    end_j = min(n, i - m + 2)

                    for j in range(start_j, end_j):
                        if str1[j] == 'F':
                            # Check if word[j:j+m] equals str2
                            window_str = "".join(word[j:j+m])
                            if window_str == str2:
                                valid = False
                                break
                    if valid:
                        break

                # If no character works, return empty string
                if word[i] == '':
                    return ""

        return "".join(word)

import bisect
from typing import List

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        if n == 0:
            return []

        # Store (l, r, weight, original_index)
        # We keep the original index to handle lexicographical order correctly
        sorted_intervals = sorted(intervals, key=lambda x: (x[1], x[0]))

        # Coordinate compression for start times
        start_times = sorted(set(x[0] for x in sorted_intervals))
        start_map = {val: i for i, val in enumerate(start_times)}
        m = len(start_times)

        # Segment Tree for range max query
        class SegmentTree:
            def __init__(self, size):
                self.n = 1
                while self.n < size:
                    self.n *= 2
                self.tree = [-1] * (2 * self.n)

            def update(self, i, val):
                i += self.n
                self.tree[i] = max(self.tree[i], val)
                while i > 1:
                    self.tree[i >> 1] = max(self.tree[i >> 1], self.tree[i])
                    i >>= 1

            def query(self, l, r):
                if l > r:
                    return -1
                l += self.n
                r += self.n
                res = -1
                while l <= r:
                    if l % 2 == 1:
                        res = max(res, self.tree[l])
                        l += 1
                    if r % 2 == 0:
                        res = max(res, self.tree[r])
                        r -= 1
                    l >>= 1
                    r >>= 1
                return res

        # dp[k][i] = max weight using exactly k intervals ending with sorted_intervals[i]
        dp = [[-1] * n for _ in range(5)]

        # Base case: k=1
        for i in range(n):
            dp[1][i] = sorted_intervals[i][2]

        # Precompute end times for binary search
        end_times = [x[1] for x in sorted_intervals]

        # Fill DP for k=2 to 4
        for k in range(2, 5):
            # Precompute prefix max for dp[k-1]
            prefix_max = [-1] * n
            current_max = -1
            for idx in range(n):
                current_max = max(current_max, dp[k-1][idx])
                prefix_max[idx] = current_max

            for i in range(n):
                l, r, w = sorted_intervals[i]
                # Find largest index 'ptr' such that sorted_intervals[ptr].end < l
                # bisect_left gives the first index where end_times[idx] >= l
                idx = bisect.bisect_left(end_times, l)
                if idx > 0:
                    best_prev = prefix_max[idx-1]
                    if best_prev != -1:
                        dp[k][i] = best_prev + w

        # Find global max weight
        max_w = 0
        for k in range(1, 5):
            for i in range(n):
                if dp[k][i] > max_w:
                    max_w = dp[k][i]

        if max_w == 0:
            return []

        # suffix_dp[k][i] = max weight using exactly k intervals starting with sorted_intervals[i]
        suffix_dp = [[-1] * n for _ in range(5)]

        # Initialize for k=1
        for i in range(n):
            suffix_dp[1][i] = sorted_intervals[i][2]

        # Build Segment Tree with k=1 values
        st = SegmentTree(m)
        for i in range(n):
            rank = start_map[sorted_intervals[i][0]]
            st.update(rank, suffix_dp[1][i])

        # Compute suffix_dp for k=2 to 4
        for k in range(2, 5):
            for i in range(n):
                l, r, w = sorted_intervals[i]
                # We need max(suffix_dp[k-1][j]) for all j such that start_j > r
                # Find smallest rank such that start_times[rank] > r
                idx = bisect.bisect_right(start_times, r)
                if idx < m:
                    best = st.query(idx, m-1)
                    if best != -1:
                        suffix_dp[k][i] = w + best

            # Update ST with suffix_dp[k] values
            for i in range(n):
                rank = start_map[sorted_intervals[i][0]]
                st.update(rank, suffix_dp[k][i])

        best_seq = None

        # Reconstruct lexicographically smallest sequence
        # Check lengths 1 to 4
        for L in range(1, 5):
            current_weight = max_w
            current_end = -1
            seq = []
            possible = True

            for step in range(1, L + 1):
                found = False
                # Iterate original indices to find the lexicographically smallest valid next interval
                for v in range(n):
                    # Check start constraint (non-overlapping)
                    if step > 1:
                        if intervals[v][0] <= current_end:
                            continue

                    rem_weight = current_weight - intervals[v][2]

                    # Check if we can complete the sequence
                    if step == L:
                        # Last interval, remaining weight must be 0
                        if rem_weight != 0:
                            continue
                    else:
                        # Need to check if there exists a sequence of length L-step starting after v
                        # with weight rem_weight.
                        # This is equivalent to: max_{j: start_j > intervals[v].end} suffix_dp[L-step][j] == rem_weight
                        end_v = intervals[v][1]
                        max_rem = -1

                        # Optimization: We can iterate all j. Since N=50000 and L is small, this is acceptable.
                        # O(N) per step, total O(N*L^2) ~ 50000 * 16 = 800,000 operations.
                        for j in range(n):
                            if intervals[j][0] > end_v:
                                if suffix_dp[L-step][j] > max_rem:
                                    max_rem = suffix_dp[L-step][j]

                        if max_rem != rem_weight:
                            continue

                    # If we are here, v is a valid candidate.
                    seq.append(v)
                    current_end = intervals[v][1]
                    current_weight = rem_weight
                    found = True
                    break

                if not found:
                    possible = False
                    break

            if possible:
                if best_seq is None or seq < best_seq:
                    best_seq = seq

        return best_seq

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Separate numbers into those > threshold (isolated) and those <= threshold (potential connections)
        large_count = 0
        small_nums = []
        for num in nums:
            if num > threshold:
                large_count += 1
            else:
                small_nums.append(num)

        # If no numbers <= threshold, all are isolated
        if not small_nums:
            return large_count

        # Initialize DSU for small numbers
        parent = {num: num for num in small_nums}

        # Iterative find with path compression to avoid recursion depth issues
        def find(x):
            path = []
            while parent[x] != x:
                path.append(x)
                x = parent[x]
            for node in path:
                parent[node] = x
            return x

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY
                return True
            return False

        # Array to store the first number found that divides a multiple j
        # Index j corresponds to the multiple value.
        first_occurrence = [-1] * (threshold + 1)

        # Iterate through each small number and its multiples
        # Complexity: O(T log T + N) where T is threshold and N is number of small elements
        for x in small_nums:
            # Iterate multiples: x, 2x, 3x, ... <= threshold
            j = x
            while j <= threshold:
                if first_occurrence[j] != -1:
                    # We found another number that divides j, so union them
                    # Both x and first_occurrence[j] divide j, so lcm(x, first_occurrence[j]) divides j <= threshold
                    union(x, first_occurrence[j])
                else:
                    first_occurrence[j] = x
                j += x

        # Count disjoint sets in small_nums
        components_small = 0
        for num in small_nums:
            if parent[num] == num:
                components_small += 1

        return large_count + components_small
